def stream_large_log(file_path):
    with open(file_path, 'r', encoding='utf-8') as f:
        for line in f:
            if 'ERROR' in line:
                yield line.strip()

# Usage: Memory consumption stays under a few MBs!
for error_log in stream_large_log('/var/logs/huge_production.log'):
    process_error(error_log)

import time
import functools

def log_execution_time(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        start = time.time()
        res = func(*args, **kwargs)
        print(f'{func.__name__} executed in {time.time() - start:.2f}s')
        return res
    return wrapper

from contextlib import contextmanager

@contextmanager
def open_s3_stream(bucket, key):
    stream = get_s3_connection(bucket, key)
    try:
        yield stream
    finally:
        stream.close()

